CREATE OR REPLACE FUNCTION ECAMS.LAST_CHECKOUT_VER
(ITEMID IN VARCHAR2,STATUS IN VARCHAR2,LSTVER IN INTEGER,CKOUTUSER IN VARCHAR2,USERID IN VARCHAR2)
RETURN INTEGER
IS
   VVER INT := 0;

CURSOR  VERLIST    IS
   SELECT B.CR_VERSION
     FROM CMR1010 B,CMR1000 A
    WHERE B.CR_ITEMID=ITEMID
      AND B.CR_STATUS<>'3'
      AND B.CR_PRCDATE IS NOT NULL
      AND B.CR_ACPTNO=A.CR_ACPTNO
      AND A.CR_QRYCD in ('01','02')
      AND A.CR_STATUS<>'3'
      AND A.CR_PRCDATE IS NOT NULL
    ORDER by A.CR_PRCDATE DESC;

--체크아웃버전 추출
BEGIN
   IF STATUS = '0' OR STATUS = '9' OR STATUS = '3' THEN RETURN LSTVER;
   ELSIF LSTVER = 0 THEN RETURN LSTVER;
   ELSIF CKOUTUSER IS NULL THEN RETURN LSTVER;
   ELSIF CKOUTUSER <> USERID THEN RETURN LSTVER;
   ELSE
      VVER := LSTVER;
   END IF;

   For Usr2 In VERLIST  Loop
      VVER := Usr2.CR_VERSION;
      Exit;
   End Loop;

   RETURN VVER;

end;